style.css:
@-moz-document domain("youtube.com") {
body, ytd-app, #content, #page-manager {
        font-family: 'Poppins', sans-serif !important;
        background-color: #0d0d0d !important;
        color: #e5e5e5 !important;
    }

    /* ============================= */
    /*  BUTTON STYLE                 */
    /* ============================= */
    button, tp-yt-paper-button, a#logo, a.yt-simple-endpoint {
        border-radius: 12px !important; /* rounded square */
        background-color: #1c1c1c !important;
        color: #fff !important;
        border: none !important;
        padding: 10px 16px !important;
        cursor: pointer;
        position: relative;
        overflow: hidden;
        transition: all 0.25s ease-in-out !important;
    }

    /* Hover jiggle */
    button:hover, tp-yt-paper-button:hover, a#logo:hover, a.yt-simple-endpoint:hover {
        transform: scale(1.08) rotate(-1deg) !important;
        box-shadow: 0 6px 12px rgba(255,255,255,0.1) !important;
    }

    /* Shine overlay for buttons */
    button::before, tp-yt-paper-button::before {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: inherit;
        background: linear-gradient(135deg, rgba(255,255,255,0.2) 0%, rgba(255,255,255,0) 70%);
        mix-blend-mode: overlay;
        pointer-events: none;
        transition: transform 0.3s ease !important;
    }

    /* Ripple click effect */
    button:active::after, tp-yt-paper-button:active::after {
        content: '';
        position: absolute;
        left: 50%;
        top: 50%;
        width: 200%;
        height: 200%;
        background: rgba(255,255,255,0.15);
        border-radius: 50%;
        transform: translate(-50%, -50%) scale(0);
        animation: ripple 0.6s ease-out forwards;
    }

    @keyframes ripple {
        to {
            transform: translate(-50%, -50%) scale(1);
            opacity: 0;
        }
    }

    /* ============================= */
    /*  DARK MODE / BACKGROUNDS      */
    /* ============================= */
    ytd-masthead, #masthead-container, #guide, #content, ytd-watch-flexy, #columns {
        background-color: #0a0a0a !important;
    }

    /* Video cards / previews */
    ytd-rich-grid-media, ytd-video-renderer, ytd-grid-video-renderer {
        background-color: #121212 !important;
        border-radius: 12px !important;
        overflow: hidden !important;
        transition: transform 0.3s ease !important;
    }

    ytd-rich-grid-media:hover, ytd-video-renderer:hover, ytd-grid-video-renderer:hover {
        transform: scale(1.02) !important;
        box-shadow: 0 6px 12px rgba(255,255,255,0.05) !important;
    }

    /* Icons */
    yt-icon, svg {
        fill: #e5e5e5 !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px !important;
    }
    ::-webkit-scrollbar-track {
        background: #0d0d0d !important;
    }
    ::-webkit-scrollbar-thumb {
        background-color: #333 !important;
        border-radius: 10px !important;
    }
}
